// Settings, trigger and run id. This node never throws, so a Run Now caller always gets a clear answer.
const problems = [];
const text = v => (v === undefined || v === null) ? '' : String(v).trim();
const required = {
  AIRTABLE_TOKEN: text($env.AIRTABLE_TOKEN),
  AIRTABLE_BASE_ID: text($env.AIRTABLE_BASE_ID),
  SHOPIFY_STORE_DOMAIN: text($env.SHOPIFY_STORE_DOMAIN),
  SHOPIFY_ADMIN_TOKEN: text($env.SHOPIFY_ADMIN_TOKEN),
  SHOPIFY_LOCATION_ID: text($env.SHOPIFY_LOCATION_ID),
};
for (const [name, value] of Object.entries(required)) if (!value) problems.push(`${name} is empty`);
if (required.AIRTABLE_BASE_ID && !/^app[A-Za-z0-9]{14}$/.test(required.AIRTABLE_BASE_ID))
  problems.push('AIRTABLE_BASE_ID does not look like an Airtable base id (app plus 14 letters or digits)');
if (required.SHOPIFY_STORE_DOMAIN && !/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/i.test(required.SHOPIFY_STORE_DOMAIN))
  problems.push('SHOPIFY_STORE_DOMAIN must be the store domain that ends in .myshopify.com, without the protocol');
if (required.SHOPIFY_LOCATION_ID && !/^gid:\/\/shopify\/Location\/\d+$/.test(required.SHOPIFY_LOCATION_ID))
  problems.push('SHOPIFY_LOCATION_ID must look like gid://shopify/Location/123456');
const apiVersion = text($env.SHOPIFY_API_VERSION) || '2026-10';
if (!/^\d{4}-(01|04|07|10)$/.test(apiVersion)) problems.push('SHOPIFY_API_VERSION must look like 2026-10');
else if (apiVersion < '2026-04') problems.push('SHOPIFY_API_VERSION must be 2026-04 or newer, because the stock update uses changeFromQuantity and @idempotent');

function wholeNumber(name, raw, fallback, min, max) {
  const t = text(raw);
  if (t === '') return fallback;
  const n = Number(t);
  if (!Number.isInteger(n) || n < min || n > max) {
    problems.push(`${name} must be a whole number from ${min} to ${max}`);
    return fallback;
  }
  return n;
}
const bufferDays = wholeNumber('SELL_BY_BUFFER_DAYS', $env.SELL_BY_BUFFER_DAYS, 14, 0, 365);
const promoDays = wholeNumber('PROMO_WINDOW_DAYS', $env.PROMO_WINDOW_DAYS, 45, 0, 730);
const discountPercent = wholeNumber('PROMO_DISCOUNT_PERCENT', $env.PROMO_DISCOUNT_PERCENT, 25, 1, 90);
if (promoDays !== 0 && promoDays <= bufferDays)
  problems.push('PROMO_WINDOW_DAYS must be larger than SELL_BY_BUFFER_DAYS (or 0 to switch promos off), otherwise no sellable batch can get a promo');

let trigger = 'Schedule';
try { if ($('Webhook: Run Now').isExecuted) trigger = 'Run Now'; } catch (e) {}
const startedAt = new Date().toISOString();
// The Sync Log Run ID, for example inventory-2026-10-21T06:00:00Z-48213. The n8n execution id keeps it unique, so two
// runs started in the same second (a double click on Run Now) still get one row each.
const runId = 'inventory-' + startedAt.slice(0, 19) + 'Z-' + $execution.id;

return [{ json: {
  ok: problems.length === 0, problems, trigger, runNow: trigger === 'Run Now', runId, startedAt,
  today: startedAt.slice(0, 10),                              // every date rule works on UTC calendar days
  bufferDays, promoDays, discountPercent, apiVersion,
  locationId: required.SHOPIFY_LOCATION_ID,
  slackEnabled: text($env.SLACK_WEBHOOK_URL) !== '',
  productsQuery: {
    pageSize: 100,
    filterByFormula: "{Status} = 'Active'",
    fields: ['SKU', 'Name', 'Shopify Inventory Item ID', 'Shopify Stock', 'Reorder Point', 'Reorder Quantity'],
  },
} }];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
// A paginated read stops after maxRequests pages. If the last page still has an offset, the read was cut short:
// stop before anything changes rather than work with part of a table (fewer batches would mean too little stock).
function allRecords(node, table) {
  const pages = $(node).all();
  const last = pages.length ? pages[pages.length - 1].json : {};
  if (last && last.offset) {
    throw new Error(`The ${table} read stopped after ${pages.length} page${pages.length === 1 ? '' : 's'} with more records `
      + `left, so the run stopped before changing anything. Raise maxRequests in ${node.replace(': ', ' ')}`);
  }
  return pages.flatMap(page => page.json.records || []);
}

// One entry per active product. A number that is not set comes back as null (Airtable leaves empty cells out).
const num = v => (typeof v === 'number' && Number.isFinite(v)) ? v : null;
const products = allRecords('Airtable: List Products', 'Products').map(r => {
  const f = r.fields || {};
  return {
    id: r.id,
    sku: String(f.SKU || '').trim(),
    name: f.Name || '',
    itemId: String(f['Shopify Inventory Item ID'] || '').trim(),
    airtableStock: num(f['Shopify Stock']),
    reorderPoint: num(f['Reorder Point']),
    reorderQuantity: num(f['Reorder Quantity']),
  };
});
await sleep(500);   // Airtable allows 5 requests per second per base. Every call waits 500 ms after the last one, so even two runs at
// the same moment (a double click on Run Now) stay at 4 calls per second together
return [{ json: {
  products,
  batchesQuery: {
    pageSize: 100,
    filterByFormula: "OR({Status} = 'Released', {Status} = 'Planned')",
    fields: ['Batch Code', 'Product', 'Status', 'Produced On', 'Best Before', 'Quantity Made', 'Quantity Reserved', 'Quantity Sold', 'Promos'],
  },
} }];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
// A paginated read stops after maxRequests pages. If the last page still has an offset, the read was cut short:
// stop before anything changes rather than work with part of a table (fewer batches would mean too little stock).
function allRecords(node, table) {
  const pages = $(node).all();
  const last = pages.length ? pages[pages.length - 1].json : {};
  if (last && last.offset) {
    throw new Error(`The ${table} read stopped after ${pages.length} page${pages.length === 1 ? '' : 's'} with more records `
      + `left, so the run stopped before changing anything. Raise maxRequests in ${node.replace(': ', ' ')}`);
  }
  return pages.flatMap(page => page.json.records || []);
}

// Sellable stock per SKU, worked out from the production batches (Airtable is the source of truth).
// A batch counts when it is Released, was produced on or before today and has MORE than SELL_BY_BUFFER_DAYS left
// before its best before date. Its units are Quantity Made minus Quantity Reserved minus Quantity Sold (never below 0).
// Batches are kept in FIFO order (earliest best before first): that is the order the packing team should ship them.
const run = $('Code: Start Run').first().json;
const products = $('Code: Index Products').first().json.products;
const batches = allRecords('Airtable: List Batches', 'Production Batches');
const DAY = 86400000;
const dayNumber = s => /^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))
  ? Math.round(Date.UTC(+s.slice(0, 4), +s.slice(5, 7) - 1, +s.slice(8, 10)) / DAY) : null;
const today = dayNumber(run.today);
const isNum = v => typeof v === 'number' && Number.isFinite(v);
const attention = [];   // something a person has to fix in Airtable or Shopify (goes to Slack)
const heldBack = [];    // units kept off sale because the batch is inside the sell-by buffer (Sync Log only)

const bySku = new Map(), byId = new Map();
for (const p of products) {
  if (!p.sku) { attention.push(`An active product (${p.id}) has no SKU`); continue; }
  if (bySku.has(p.sku)) { attention.push(`SKU ${p.sku} is on more than one active product, only the first one is used`); continue; }
  const entry = { ...p, sellable: 0, fifo: [], planned: [] };
  bySku.set(p.sku, entry);
  byId.set(p.id, entry);
}

const promoCandidates = [];
for (const b of batches) {
  const f = b.fields || {};
  const code = String(f['Batch Code'] || '').trim() || b.id;
  const links = f.Product || [];
  const product = byId.get(links[0]);
  if (!product) {
    if (links.length === 0) attention.push(`Batch ${code} is not linked to a product`);
    continue;   // linked to a Draft or Discontinued product: not for sale
  }
  if (links.length > 1) attention.push(`Batch ${code} is linked to ${links.length} products, it is counted for ${product.sku} only`);
  const made = f['Quantity Made'];
  if (f.Status === 'Planned') {
    const plannedDay = dayNumber(f['Produced On']);
    if (plannedDay !== null && plannedDay < today)
      attention.push(`Batch ${code} (${product.sku}) is still Planned although its Produced On date (${f['Produced On']}) has passed. Release it or move the date`);
    else if (isNum(made) && made > 0 && plannedDay !== null)
      product.planned.push({ code, units: made, producedOn: f['Produced On'] });
    continue;
  }
  if (!isNum(made)) { attention.push(`Batch ${code} (${product.sku}) has no Quantity Made, so it is not counted`); continue; }
  const reserved = isNum(f['Quantity Reserved']) ? f['Quantity Reserved'] : 0;
  const sold = isNum(f['Quantity Sold']) ? f['Quantity Sold'] : 0;
  if (made - reserved - sold < 0)
    attention.push(`Batch ${code} (${product.sku}) has more units reserved and sold (${reserved + sold}) than made (${made}), so it counts as 0`);
  const units = Math.max(made - reserved - sold, 0);
  if (units === 0) continue;
  const produced = dayNumber(f['Produced On']);
  const bestBefore = dayNumber(f['Best Before']);
  if (produced === null || bestBefore === null) {
    attention.push(`Batch ${code} (${product.sku}) has no Produced On or Best Before date, so its ${units} units are not counted`);
    continue;
  }
  const daysLeft = bestBefore - today;
  if (produced > today) {
    attention.push(`Batch ${code} (${product.sku}) is Released but its Produced On date (${f['Produced On']}) is in the future, so its ${units} units are not counted`);
    continue;
  }
  if (daysLeft < 0) {
    attention.push(`Batch ${code} (${product.sku}) is past its best before date (${f['Best Before']}) but still marked Released, ${units} units`);
    continue;
  }
  if (daysLeft <= run.bufferDays) {
    heldBack.push({ code, sku: product.sku, units, daysLeft, bestBefore: f['Best Before'] });
    continue;
  }
  const lot = { code, recordId: b.id, units, daysLeft, bestBefore: f['Best Before'], producedOn: f['Produced On'] };
  product.sellable += units;
  product.fifo.push(lot);
  if (run.promoDays > 0 && daysLeft <= run.promoDays)
    promoCandidates.push({ ...lot, sku: product.sku, productId: product.id, name: 'PROMO-' + code, linked: (f.Promos || []).length > 0 });
}

const fifoOrder = (a, b) => a.bestBefore.localeCompare(b.bestBefore) || String(a.producedOn).localeCompare(String(b.producedOn)) || a.code.localeCompare(b.code);
const all = [...bySku.values()];
for (const s of all) {
  s.fifo.sort(fifoOrder);
  s.planned.sort((a, b) => a.producedOn.localeCompare(b.producedOn));
  s.fifoText = s.fifo.map(l => `${l.code} ${l.units}`).join(', ');
}

// Only Active products that have a Shopify Inventory Item ID are pushed to Shopify. Others (wholesale only, drafts)
// are left alone, so their Shopify stock is never set to 0 by mistake.
const LIMIT = 250;   // nodes(ids:) reads at most 250 inventory items in one query
const sync = [], notOnShopify = [];
for (const s of all) {
  if (!s.itemId) { notOnShopify.push(s.sku); continue; }
  if (!/^gid:\/\/shopify\/InventoryItem\/\d+$/.test(s.itemId)) {
    attention.push(`${s.sku} has a Shopify Inventory Item ID that is not a Shopify inventory item id (${s.itemId}), so it was not synced`);
    continue;
  }
  sync.push({ sku: s.sku, productId: s.id, itemId: s.itemId, sellable: s.sellable, airtableStock: s.airtableStock, fifoText: s.fifoText });
}
sync.sort((a, b) => a.sku.localeCompare(b.sku));
if (sync.length > LIMIT) {
  attention.push(`${sync.length} products have a Shopify Inventory Item ID, only the first ${LIMIT} by SKU were synced`);
  sync.length = LIMIT;
}

// Purchasing Requests: sellable stock strictly below the reorder point
const reorder = all.filter(s => isNum(s.reorderPoint) && s.sellable < s.reorderPoint).map(s => ({
  sku: s.sku, productId: s.id, sellable: s.sellable, reorderPoint: s.reorderPoint, reorderQuantity: s.reorderQuantity, planned: s.planned,
}));

promoCandidates.sort((a, b) => a.daysLeft - b.daysLeft || a.code.localeCompare(b.code));
await sleep(500);
return [{ json: {
  sync, notOnShopify, promoCandidates, reorder, attention, heldBack,
  sellableBySku: Object.fromEntries(all.map(s => [s.sku, s.sellable])),
  // A request stays in progress while it is Open or Scheduled (the kitchen planned the batch, the stock is still low)
  openRequestsQuery: { pageSize: 100, filterByFormula: "OR({Status} = 'Open', {Status} = 'Scheduled')",
                       fields: ['Request ID', 'SKU', 'Product', 'Status'] },
} }];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
// A paginated read stops after maxRequests pages. If the last page still has an offset, the read was cut short:
// stop before anything changes rather than work with part of a table (fewer batches would mean too little stock).
function allRecords(node, table) {
  const pages = $(node).all();
  const last = pages.length ? pages[pages.length - 1].json : {};
  if (last && last.offset) {
    throw new Error(`The ${table} read stopped after ${pages.length} page${pages.length === 1 ? '' : 's'} with more records `
      + `left, so the run stopped before changing anything. Raise maxRequests in ${node.replace(': ', ' ')}`);
  }
  return pages.flatMap(page => page.json.records || []);
}

// Skip SKUs that already have a purchasing request in progress (Open or Scheduled), and batches whose promo exists.
const c = $('Code: Compute Sellable').first().json;
const open = allRecords('Airtable: List Open Requests', 'Purchasing Requests');
const statusBySku = new Map(), statusByProduct = new Map();
for (const r of open) {
  const f = r.fields || {};
  if (f.SKU) statusBySku.set(String(f.SKU).trim(), f.Status);
  for (const id of f.Product || []) statusByProduct.set(id, f.Status);
}
const statusOf = x => statusBySku.get(x.sku) || statusByProduct.get(x.productId);
const newRequests = c.reorder.filter(x => !statusOf(x));
const requestsAlreadyOpen = c.reorder.filter(x => statusOf(x)).map(x => `${x.sku} (${statusOf(x)})`);

// A batch that already links to a promo is done. The rest are looked up by Promo Name (PROMO-<batch code>), in case a
// promo was made by hand without the link. The match ignores case and spaces around the name, because a hand typed
// name may differ there. Text in a formula is quoted and escaped.
const promoToCheck = c.promoCandidates.filter(p => !p.linked);
const promosAlreadyLinked = c.promoCandidates.filter(p => p.linked).map(p => p.name);
const quote = s => "'" + String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const formula = promoToCheck.length
  ? 'OR(' + promoToCheck.map(p => 'LOWER(TRIM({Promo Name})) = ' + quote(p.name.toLowerCase())).join(', ') + ')'
  : 'FALSE()';
await sleep(500);
return [{ json: {
  newRequests, requestsAlreadyOpen, promoToCheck, promosAlreadyLinked,
  promosQuery: { pageSize: 100, filterByFormula: formula, fields: ['Promo Name', 'Status'] },
} }];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
// The error item of an HTTP Request node (checked on n8n 2.19.5) comes in two shapes:
//   no pagination: error.status, and error.message = '<status> - "<response body as JSON text>"' (for a 429 n8n
//                  replaces the message, so the status decides)
//   pagination on: error.statusCode and error.response.status, and error.error = the response body as JSON text
function httpErrorText(e) {
  if (!e) return 'unknown error';
  const status = e.status || e.statusCode || (e.response && e.response.status) || '';
  const m = String(e.message || '');
  let body = null;
  try { body = JSON.parse(JSON.parse(m.slice(m.indexOf(' - ') + 3))); } catch (x) {}
  if (!body && typeof e.error === 'string') { try { body = JSON.parse(e.error); } catch (x) {} }
  let detail = '';
  if (body && typeof body === 'object') {
    if (typeof body.error === 'string') detail = body.error;
    else if (body.error && typeof body.error === 'object') detail = [body.error.type, body.error.message].filter(Boolean).join(' ');
    else if (typeof body.errors === 'string') detail = body.errors;
    else if (Array.isArray(body.errors)) detail = body.errors.map(x => x.message || x.code).join(', ');
  }
  if (String(status) === '429' && !detail) detail = 'rate limit reached';
  if (!detail) detail = m.replace(/^\d{3} - /, '').slice(0, 200) || 'no details';
  return [status, detail].filter(Boolean).join(' ');
}

// One of the Airtable reads failed after its retries. Nothing has been changed yet, so the run stops here. It still
// tries to leave a Failed row in the Sync Log: the usual cause is a renamed field or table (422), and then Airtable
// takes the write. If Airtable is down the write fails as well and the alert says so.
const run = $('Code: Start Run').first().json;
const order = ['Airtable: Find Existing Promos', 'Airtable: List Open Requests', 'Airtable: List Batches', 'Airtable: List Products'];
let failed = 'Airtable';
for (const name of order) {
  try { if ($(name).isExecuted) { failed = name; break; } } catch (e) {}
}
const what = failed.replace('Airtable: ', '');
const message = `Airtable read failed at ${what} (${httpErrorText($input.first().json.error)}). Nothing was changed, run the sync again once Airtable answers.`;
const fields = {
  'Run ID': run.runId, Automation: '02 Inventory Sync', Trigger: run.trigger, 'Started At': run.startedAt,
  'Finished At': new Date().toISOString(), Status: 'Failed', 'Items Checked': 0, 'Items Changed': 0, 'Shopify Updates': 0,
  'Promos Created': 0, 'Purchasing Requests Created': 0, Errors: 1,
  Details: `${run.trigger} run, started ${run.startedAt}.\n${message}`,
};
await sleep(500);
return [{ json: { message, syncLogBody: { performUpsert: { fieldsToMergeOn: ['Run ID'] }, typecast: false, records: [{ fields }] } } }];

// A paginated read stops after maxRequests pages. If the last page still has an offset, the read was cut short:
// stop before anything changes rather than work with part of a table (fewer batches would mean too little stock).
function allRecords(node, table) {
  const pages = $(node).all();
  const last = pages.length ? pages[pages.length - 1].json : {};
  if (last && last.offset) {
    throw new Error(`The ${table} read stopped after ${pages.length} page${pages.length === 1 ? '' : 's'} with more records `
      + `left, so the run stopped before changing anything. Raise maxRequests in ${node.replace(': ', ' ')}`);
  }
  return pages.flatMap(page => page.json.records || []);
}

// One Shopify query reads the location and, for every synced SKU, its inventory item and the available and
// committed quantities at that location. committed = units in orders that are placed but not fulfilled yet.
allRecords('Airtable: Find Existing Promos', 'Promos');   // the last read: refuse it here if it was cut short
const run = $('Code: Start Run').first().json;
const c = $('Code: Compute Sellable').first().json;
const query = `query StockLevels($ids: [ID!]!, $locationId: ID!) {
  location(id: $locationId) { id name isActive }
  nodes(ids: $ids) {
    ... on InventoryItem {
      id
      sku
      tracked
      inventoryLevel(locationId: $locationId) {
        quantities(names: ["available", "committed"]) { name quantity }
      }
    }
  }
}`;
return [{ json: { body: { query, operationName: 'StockLevels', variables: { ids: c.sync.map(s => s.itemId), locationId: run.locationId } } } }];

// The error item of an HTTP Request node (checked on n8n 2.19.5) comes in two shapes:
//   no pagination: error.status, and error.message = '<status> - "<response body as JSON text>"' (for a 429 n8n
//                  replaces the message, so the status decides)
//   pagination on: error.statusCode and error.response.status, and error.error = the response body as JSON text
function httpErrorText(e) {
  if (!e) return 'unknown error';
  const status = e.status || e.statusCode || (e.response && e.response.status) || '';
  const m = String(e.message || '');
  let body = null;
  try { body = JSON.parse(JSON.parse(m.slice(m.indexOf(' - ') + 3))); } catch (x) {}
  if (!body && typeof e.error === 'string') { try { body = JSON.parse(e.error); } catch (x) {} }
  let detail = '';
  if (body && typeof body === 'object') {
    if (typeof body.error === 'string') detail = body.error;
    else if (body.error && typeof body.error === 'object') detail = [body.error.type, body.error.message].filter(Boolean).join(' ');
    else if (typeof body.errors === 'string') detail = body.errors;
    else if (Array.isArray(body.errors)) detail = body.errors.map(x => x.message || x.code).join(', ');
  }
  if (String(status) === '429' && !detail) detail = 'rate limit reached';
  if (!detail) detail = m.replace(/^\d{3} - /, '').slice(0, 200) || 'no details';
  return [status, detail].filter(Boolean).join(' ');
}

function gqlErrorText(errors) {
  if (typeof errors === 'string') return errors.slice(0, 300);
  return (errors || []).map(e => {
    const code = e && e.extensions && e.extensions.code;
    const msg = (e && e.message) || '';
    return code && msg && msg !== code ? code + ' ' + msg : (code || msg);
  }).join(', ').slice(0, 300) || 'unknown GraphQL error';
}

// Compare what Shopify shows with what Airtable says is sellable, and plan one inventorySetQuantities call per SKU
// that differs. Target = sellable minus committed: units already promised to unshipped Shopify orders stay out of
// "available", otherwise they could be sold twice. changeFromQuantity is the available quantity Shopify returned a
// moment ago, so a sale that lands in between makes Shopify refuse the change instead of overwriting it.
const run = $('Code: Start Run').first().json;
const c = $('Code: Compute Sellable').first().json;
const res = $input.first().json;
const MUTATION = `mutation SetStock($input: InventorySetQuantitiesInput!, $key: String!) {
  inventorySetQuantities(input: $input) @idempotent(key: $key) {
    inventoryAdjustmentGroup { id reason referenceDocumentUri changes { name delta quantityAfterChange } }
    userErrors { code field message }
  }
}`;

let readError = null, location = null, found = [];
if (res.error) readError = `Shopify stock could not be read (${httpErrorText(res.error)})`;
else if (res.errors) readError = `Shopify refused the stock query (${gqlErrorText(res.errors)})`;
else if (!res.data) readError = 'Shopify answered the stock query without data';
else {
  location = res.data.location;
  if (!location) readError = `Shopify has no location ${run.locationId}, check SHOPIFY_LOCATION_ID`;
  else if (!location.isActive) readError = `The Shopify location ${location.name} is not active, so its stock cannot be set (check SHOPIFY_LOCATION_ID)`;
  else found = (res.data.nodes || []).filter(Boolean);
}

const byItem = new Map(found.map(n => [n.id, n]));
const changes = [], inSync = [], skipped = [];
if (!readError) {
  for (const s of c.sync) {
    const n = byItem.get(s.itemId);
    const skip = reason => skipped.push({ sku: s.sku, reason });
    if (!n) { skip(`its Shopify Inventory Item ID ${s.itemId} was not found in Shopify`); continue; }
    if (String(n.sku || '').trim() !== s.sku) { skip(`its Shopify Inventory Item ID belongs to SKU ${n.sku || '(no SKU)'} in Shopify`); continue; }
    if (!n.tracked) { skip('Shopify does not track inventory for it'); continue; }
    if (!n.inventoryLevel) { skip(`it is not stocked at ${location.name} in Shopify`); continue; }
    const q = {};
    for (const x of n.inventoryLevel.quantities || []) q[x.name] = x.quantity;
    const live = q.available;
    if (!Number.isInteger(live)) { skip('Shopify did not return an available quantity'); continue; }
    const committed = Math.max(Number(q.committed) || 0, 0);
    const target = Math.max(s.sellable - committed, 0);
    const base = { sku: s.sku, productId: s.productId, itemId: s.itemId, live, target, committed, sellable: s.sellable,
                   airtableStock: s.airtableStock, fifoText: s.fifoText };
    if (target === live) { inSync.push(base); continue; }
    // Same key on a retry (so Shopify replays the first answer), a new key for every new run or start value. The run
    // id already holds the n8n execution id, so two runs in the same second never share a key.
    const key = `${run.runId}-${s.sku}-${live}`;
    changes.push({ ...base, key, body: { query: MUTATION, operationName: 'SetStock', variables: { key, input: {
      name: 'available',
      reason: 'correction',
      referenceDocumentUri: `gid://airtable-inventory-sync/SyncRun/${run.runId}`,
