// The error item of an HTTP Request node (checked on n8n 2.19.5) comes in two shapes:
//   no pagination: error.status, and error.message = '<status> - "<response body as JSON text>"' (for a 429 n8n
//                  replaces the message, so the status decides)
//   pagination on: error.statusCode and error.response.status, and error.error = the response body as JSON text
function httpErrorText(e) {
  if (!e) return 'unknown error';
  const status = e.status || e.statusCode || (e.response && e.response.status) || '';
  const m = String(e.message || '');
  let body = null;
  try { body = JSON.parse(JSON.parse(m.slice(m.indexOf(' - ') + 3))); } catch (x) {}
  if (!body && typeof e.error === 'string') { try { body = JSON.parse(e.error); } catch (x) {} }
  let detail = '';
  if (body && typeof body === 'object') {
    if (typeof body.error === 'string') detail = body.error;
    else if (body.error && typeof body.error === 'object') detail = [body.error.type, body.error.message].filter(Boolean).join(' ');
