function gqlErrorText(errors) {
  if (typeof errors === 'string') return errors.slice(0, 300);
  return (errors || []).map(e => {
    const code = e && e.extensions && e.extensions.code;
    const msg = (e && e.message) || '';
    return code && msg && msg !== code ? code + ' ' + msg : (code || msg);
  }).join(', ').slice(0, 300) || 'unknown GraphQL error';
}

// One SKU per pass. The error output keeps the input fields; the success output is Shopify's answer only.
const r = $input.first().json;
const change = r.sku ? r : $('Loop: Each Stock Change').itemMatching(0).json;
let ok = false, after = null, error = null;
if (r.error) error = `Shopify call failed (${httpErrorText(r.error)})`;
else if (r.errors) error = `Shopify refused the update (${gqlErrorText(r.errors)})`;
else {
  const p = r.data && r.data.inventorySetQuantities;
  const userErrors = (p && p.userErrors) || [];
  if (!p) error = 'Shopify answered without a result';
  else if (userErrors.length) error = userErrors.map(e => e.code === 'CHANGE_FROM_QUANTITY_STALE'
