    : `${e.code || 'ERROR'} ${e.message || ''}`.trim()).join('; ');
  else if (!p.inventoryAdjustmentGroup) error = 'Shopify returned no inventory adjustment';
  else {
    ok = true;
    const avail = (p.inventoryAdjustmentGroup.changes || []).find(x => x.name === 'available');
    after = avail && Number.isInteger(avail.quantityAfterChange) ? avail.quantityAfterChange : change.target;
