}
const { body, plan, ...rest } = change;
return [{ json: { ...rest, ok, after, error }, pairedItem: { item: 0 } }];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
// Everything that goes back to Airtable, 10 records per call (Airtable's limit), in this order:
// Products (the stock Shopify now shows), new Promos (upsert on Promo Name), new Purchasing Requests (upsert on SKU
// and Status, so two runs at the same moment still cannot open two requests for one SKU).
const run = $('Code: Start Run').first().json;
const pp = $('Code: Plan Promos And Requests').first().json;
const plan = $('Code: Plan Stock Changes').first().json.plan;
const stockResults = $input.all().map(i => i.json).filter(j => typeof j.ok === 'boolean');
const existing = new Set($('Airtable: Find Existing Promos').all().flatMap(page => page.json.records || [])
  .map(r => String((r.fields || {})['Promo Name'] || '').trim().toLowerCase()));
const isNum = v => typeof v === 'number' && Number.isFinite(v);
const now = new Date().toISOString();
const chunk = list => { const out = []; for (let i = 0; i < list.length; i += 10) out.push(list.slice(i, i + 10)); return out; };
const writes = [];

// 1. Products. Pushed SKUs get the new number and Stock Synced At. A SKU that was already right in Shopify but shows a
//    different Shopify Stock in Airtable (for example after a failed write last run) is corrected without a push.
const productRecords = [];
for (const r of stockResults) if (r.ok) productRecords.push({ sku: r.sku, record: { id: r.productId, fields: { 'Shopify Stock': r.after, 'Stock Synced At': now } } });
for (const s of plan.inSync) if (s.airtableStock !== s.live) productRecords.push({ sku: s.sku, record: { id: s.productId, fields: { 'Shopify Stock': s.live } } });
for (const part of chunk(productRecords))
  writes.push({ kind: 'products', table: 'Products', method: 'PATCH', labels: part.map(p => p.sku),
                body: { records: part.map(p => p.record), typecast: false } });

// 2. Promos, one per short dated batch
const newPromos = pp.promoToCheck.filter(p => !existing.has(p.name.toLowerCase()));
const promosFoundByName = pp.promoToCheck.filter(p => existing.has(p.name.toLowerCase())).map(p => p.name);
for (const part of chunk(newPromos))
  writes.push({ kind: 'promos', table: 'Promos', method: 'PATCH', labels: part.map(p => p.name), body: {
    performUpsert: { fieldsToMergeOn: ['Promo Name'] }, typecast: false,
    records: part.map(p => ({ fields: {
      'Promo Name': p.name, Batch: [p.recordId], Product: [p.productId], 'Best Before': p.bestBefore,
      'Units Available': p.units, 'Discount Percent': run.discountPercent, Status: 'Proposed', 'Created At': now,
    } })),
  } });

// 3. Purchasing Requests, one Open request per SKU
const requestNote = x => {
  let note = `Raised by the inventory sync (${run.runId}). Sellable ${x.sellable}, reorder point ${x.reorderPoint}.`;
  if (x.planned.length) note += ' Already planned ' + x.planned.map(p => `${p.code} (${p.units} units on ${p.producedOn})`).join(', ') + '.';
  return note;
};
for (const part of chunk(pp.newRequests))
  writes.push({ kind: 'requests', table: 'Purchasing Requests', method: 'PATCH', labels: part.map(x => x.sku), body: {
    performUpsert: { fieldsToMergeOn: ['SKU', 'Status'] }, typecast: false,
    records: part.map(x => {
      const fields = { 'Request ID': `PR-${x.sku}-${run.today}`, Product: [x.productId], SKU: x.sku, Status: 'Open',
                       'Sellable Stock': x.sellable, 'Reorder Point': x.reorderPoint, 'Requested At': now, Notes: requestNote(x) };
      if (isNum(x.reorderQuantity)) fields['Suggested Quantity'] = x.reorderQuantity;
      return { fields };
    }),
  } });

const context = {
  stockResults,
  newPromos: newPromos.map(p => ({ name: p.name, sku: p.sku, units: p.units, bestBefore: p.bestBefore, daysLeft: p.daysLeft })),
  promosFoundByName,
  newRequests: pp.newRequests.map(x => ({ sku: x.sku, sellable: x.sellable, reorderPoint: x.reorderPoint, reorderQuantity: x.reorderQuantity,
                                          requestId: `PR-${x.sku}-${run.today}` })),
};
await sleep(500);
if (!writes.length) return [{ json: { noWrites: true, context }, pairedItem: { item: 0 } }];
return writes.map((w, i) => ({ json: i === 0 ? { ...w, context } : w, pairedItem: { item: 0 } }));

