// One Airtable write per pass. A 429 means Airtable blocks the base for 30 seconds: wait that long and try once more.
const r = $input.first().json;
const w = r.kind ? r : $('Loop: Each Airtable Write').itemMatching(0).json;
const status = r.error ? Number(r.error.status || r.error.statusCode || (r.error.response && r.error.response.status) || 0) : 200;
const retry = !!r.error && status === 429 && !w.rateLimitRetried;
// An upsert answers which records it created and which it updated. A record that was updated already existed (for
// example a run at the same moment made it first), so only created ones count as new.
const createdIds = new Set(!r.error && Array.isArray(r.createdRecords) ? r.createdRecords : []);
const keyField = { promos: 'Promo Name', requests: 'SKU' }[w.kind];
const createdLabels = keyField && !r.error && Array.isArray(r.records)
  ? r.records.filter(x => createdIds.has(x.id)).map(x => String((x.fields || {})[keyField] || '')) : [];
const out = {
  kind: w.kind, table: w.table, method: w.method, body: w.body, labels: w.labels,
  rateLimitRetried: !!w.rateLimitRetried || retry, retry,
  ok: !r.error, status, error: r.error ? httpErrorText(r.error) : null, createdLabels,
};
if (!retry) await sleep(500);
return [{ json: out, pairedItem: { item: 0 } }];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
// The Sync Log row, the Slack note and the final status of the run.
const run = $('Code: Start Run').first().json;
const c = $('Code: Compute Sellable').first().json;
const pp = $('Code: Plan Promos And Requests').first().json;
const plan = $('Code: Plan Stock Changes').first().json.plan;
const ctx = $('Code: Plan Airtable Writes').first().json.context;
const writes = $input.all().map(i => i.json).filter(j => j.kind);
const savedLabels = kind => new Set(writes.filter(w => w.kind === kind && w.ok).flatMap(w => w.labels));
const createdLabels = kind => new Set(writes.filter(w => w.kind === kind && w.ok).flatMap(w => w.createdLabels || []));
const failedWrites = writes.filter(w => !w.ok);
const pushed = ctx.stockResults.filter(r => r.ok);
const pushFailed = ctx.stockResults.filter(r => !r.ok);
const promosSaved = savedLabels('promos'), requestsSaved = savedLabels('requests');
const promosNew = createdLabels('promos'), requestsNew = createdLabels('requests');
const promosCreated = ctx.newPromos.filter(p => promosNew.has(p.name));
const requestsCreated = ctx.newRequests.filter(x => requestsNew.has(x.sku));
// saved but not created: another run made the same promo or request a moment earlier, the upsert matched it
const promosMatched = ctx.newPromos.filter(p => promosSaved.has(p.name) && !promosNew.has(p.name)).map(p => p.name);
const requestsMatched = ctx.newRequests.filter(x => requestsSaved.has(x.sku) && !requestsNew.has(x.sku)).map(x => `${x.sku} (Open)`);

const errorLines = [];
if (plan.readError) errorLines.push(plan.readError);
for (const r of pushFailed) errorLines.push(`${r.sku} was not updated in Shopify (${r.error})`);
const writeWhat = { products: 'Shopify Stock in Products', promos: 'promos', requests: 'purchasing requests' };
for (const w of failedWrites) errorLines.push(`Airtable did not save ${writeWhat[w.kind]} for ${w.labels.join(', ')} (${w.error})`);
