const status = plan.readError ? 'Failed' : (errors ? 'Partial' : 'Success');

const where = plan.locationName ? ` at ${plan.locationName}` : '';
const stockText = r => {
  const extra = r.committed ? `, ${r.sellable} sellable minus ${r.committed} in unshipped Shopify orders` : '';
  return `${r.sku} ${r.live} to ${r.after ?? r.target}${extra}`;
};
const details = [];
details.push(`${run.trigger} run, started ${run.startedAt}.`);
if (plan.readError) details.push(`Shopify stock was not synced. ${plan.readError}.`);
else details.push(`Checked ${plan.checked} Shopify SKUs${where}. ${pushed.length} changed, ${plan.inSync.length} already correct.`);
if (pushed.length) details.push('Set in Shopify (FIFO batches in brackets): ' + pushed.map(r => `${stockText(r)} [${r.fifoText || 'no sellable batch'}]`).join('; ') + '.');
if (plan.skipped.length) details.push('Skipped: ' + plan.skipped.map(s => `${s.sku} (${s.reason})`).join('; ') + '.');
if (c.notOnShopify.length) details.push('Not on Shopify, Airtable only: ' + c.notOnShopify.join(', ') + '.');
if (c.heldBack.length) details.push(`Held back, inside the ${run.bufferDays} day sell-by buffer: ` + c.heldBack.map(h => `${h.code} ${h.sku} ${h.units} units (${h.daysLeft} days left)`).join('; ') + '.');
if (promosCreated.length) details.push(`Promos created (${run.discountPercent}% suggested): ` + promosCreated.map(p => p.name).join(', ') + '.');
const promosThere = [...pp.promosAlreadyLinked, ...ctx.promosFoundByName, ...promosMatched];
if (promosThere.length) details.push('Promos already there: ' + promosThere.join(', ') + '.');
if (requestsCreated.length) details.push('Purchasing requests created: ' + requestsCreated.map(x => x.sku).join(', ') + '.');
const requestsThere = [...pp.requestsAlreadyOpen, ...requestsMatched];
if (requestsThere.length) details.push('Purchasing requests already in progress: ' + requestsThere.join(', ') + '.');
if (c.attention.length) details.push('Needs attention: ' + c.attention.join('; ') + '.');
