  'Finished At': new Date().toISOString(), Status: status, 'Items Checked': plan.checked, 'Items Changed': pushed.length,
  'Shopify Updates': pushed.length, 'Promos Created': promosCreated.length,
  'Purchasing Requests Created': requestsCreated.length, Errors: errors, Details: detailText,
};

// Slack: only when a person has something to do or know. Long lists are cut (Slack allows 40,000 characters, and a
// note nobody can read helps nobody); the Sync Log row has everything.
const MAX_LINES = 15;
