const bullets = (list, render) => {
  const out = list.slice(0, MAX_LINES).map(x => bullet(render(x)));
  if (list.length > MAX_LINES) out.push(bullet(`and ${list.length - MAX_LINES} more, see the Sync Log row ${run.runId}`));
  return out;
};
const lines = [`*Inventory sync* ${run.runId} (${run.trigger}), ${status}`];
if (pushed.length) {
  const shown = pushed.slice(0, 20).map(stockText).join(', ') + (pushed.length > 20 ? `, and ${pushed.length - 20} more` : '');
  lines.push(`Shopify stock set for ${pushed.length} SKU${pushed.length === 1 ? '' : 's'}${where}: ` + shown);
}
if (promosCreated.length) {
  lines.push('', `*New promos (${promosCreated.length})*, ${run.discountPercent}% off suggested, Status Proposed in Airtable:`);
  lines.push(...bullets(promosCreated, p => `${p.name} for ${p.sku}, ${p.units} units, best before ${p.bestBefore} (${p.daysLeft} days left)`));
}
if (requestsCreated.length) {
  lines.push('', `*New purchasing requests (${requestsCreated.length})*:`);
  lines.push(...bullets(requestsCreated, x => `${x.sku}, ${x.sellable} sellable, reorder point ${x.reorderPoint}` + (x.reorderQuantity ? `, suggested batch ${x.reorderQuantity}` : '')));
}
const attentionLines = [...c.attention, ...plan.skipped.map(s => `${s.sku} was not synced because ${s.reason}`)];
if (attentionLines.length) {
  lines.push('', `*Needs attention (${attentionLines.length})*:`);
  lines.push(...bullets(attentionLines, a => a));
}
if (errors) {
  lines.push('', `*Errors (${errors})*:`);
  lines.push(...bullets(errorLines, e => e));
}
const sendSlack = run.slackEnabled && (promosCreated.length > 0 || requestsCreated.length > 0 || attentionLines.length > 0 || errors > 0);
const failMessage = errors
  ? `Inventory sync ${run.runId} finished with ${errors} error${errors === 1 ? '' : 's'}. ${errorLines.slice(0, 3).join('. ')}. Details are in the Sync Log.`
  : '';
await sleep(500);
return [{ json: {
  runId: run.runId, status, errors, sendSlack, slackEnabled: run.slackEnabled, slackText: lines.join('\n'), failMessage,
  syncLogBody: { performUpsert: { fieldsToMergeOn: ['Run ID'] }, typecast: false, records: [{ fields }] },
} }];

